begin;
create temp table audit_results(label text, expected text, observed text, passed boolean);
grant all on audit_results to authenticated;
create temp table audit_apps(id uuid,actor uuid,event_id uuid);
grant all on audit_apps to authenticated;
create function pg_temp.probe(label text, statement text, expected text default 'true') returns void language plpgsql as $$
declare observed text;
begin
 begin execute statement into observed; exception when others then observed := SQLSTATE || ': ' || SQLERRM; end;
end $$;
create temp table audit_objects(name text,id uuid);grant all on audit_objects to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000010","role":"authenticated"}',true);
select pg_temp.probe('participant cannot issue recovery',$q$select public.issue_recovery_token('a0221022-0000-4000-8000-000000000016',repeat('a',64),'AUDIT') is not null$q$,'42501');
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000011","role":"authenticated"}',true);
select pg_temp.probe('admin recovery token issue',$q$select public.issue_recovery_token('a0221022-0000-4000-8000-000000000016',repeat('a',64),'AUDIT')>now()$q$,'true');
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000012","role":"authenticated"}',true);
select pg_temp.probe('treasurer recovery denied',$q$select public.issue_recovery_token('a0221022-0000-4000-8000-000000000016',repeat('b',64),'AUDIT') is not null$q$,'42501');
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000010","role":"authenticated"}',true);
select pg_temp.probe('active feedback submission',$q$select (public.submit_feedback('a0221022-0000-4000-8000-000000000001',null,'festival','{"rating":5,"comment":"AUDIT"}')).id is not null$q$,'true');
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000017","role":"authenticated"}',true);
select pg_temp.probe('pending feedback blocked',$q$select (public.submit_feedback('a0221022-0000-4000-8000-000000000001',null,'festival','{"rating":5,"comment":"AUDIT"}')).id is not null$q$,'42501');
reset role;update public.profiles set gender=null where id='a0221022-0000-4000-8000-000000000020';update public.events set eligibility='{"division":"girls"}',application_questions='[{"key":"choice","label":"Choice","type":"select","required":true,"options":["A","B"]}]' where id='a0221022-0000-4000-8000-000000000004';set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000020","role":"authenticated"}',true);
select pg_temp.probe('missing gender cannot bypass division',$q$select (public.apply_to_event('a0221022-0000-4000-8000-000000000004',gen_random_uuid(),'{"choice":"A"}')).review_state::text$q$,'42501');
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000018","role":"authenticated"}',true);
select pg_temp.probe('required answer missing rejected',$q$select (public.apply_to_event('a0221022-0000-4000-8000-000000000004',gen_random_uuid(),'{}')).review_state::text$q$,'22023');
select pg_temp.probe('invalid select option rejected',$q$select (public.apply_to_event('a0221022-0000-4000-8000-000000000004',gen_random_uuid(),'{"choice":"NOT_AN_OPTION"}')).review_state::text$q$,'22023');
reset role;update public.events set eligibility='{}',application_questions='[]' where id='a0221022-0000-4000-8000-000000000004';set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000010","role":"authenticated"}',true);
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000013","role":"authenticated"}',true);
select pg_temp.probe('approve own event',$q$select (public.review_application((select id from audit_objects where name='app'),'approved')).review_state::text$q$,'approved');
select pg_temp.probe('select own event',$q$select (public.select_solo_application((select id from audit_objects where name='app'),'selected')).selection_state::text$q$,'selected');
select pg_temp.probe('configure points',$q$select public.set_event_point_rules('a0221022-0000-4000-8000-000000000004','[{"placing":1,"points":10}]') is null$q$,'false');
select pg_temp.probe('publish results first',$q$select (public.publish_unified_results('a0221022-0000-4000-8000-000000000004',jsonb_build_array(jsonb_build_object('placing',1,'applicationId',(select id from audit_objects where name='app'))))).version::text$q$,'1');
select pg_temp.probe('correct results with reason',$q$select (public.publish_unified_results('a0221022-0000-4000-8000-000000000004',jsonb_build_array(jsonb_build_object('placing',1,'applicationId',(select id from audit_objects where name='app'))),'AUDIT correction')).version::text$q$,'2');
reset role;
select pg_temp.probe('correction does not double count points',$q$select sum(pl.points)=10 from public.points_ledger pl join public.result_publications rp on rp.id=pl.publication_id where rp.event_id='a0221022-0000-4000-8000-000000000004' and rp.state='published'$q$,'true');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"a0221022-0000-4000-8000-000000000011","role":"authenticated"}',true);
select pg_temp.probe('cannot suspend own main-admin profile',$q$select (public.set_student_access('a0221022-0000-4000-8000-000000000001','a0221022-0000-4000-8000-000000000011','suspended','AUDIT')).state::text$q$,'22023');
reset role;select * from audit_results;rollback;
